   207	func TestBuildCondensedTranscript_SkipsSkillContentInjection(t *testing.T) {
   208		skillContent := `Base directory for this skill: /Users/alex/.claude/plugins/cache/superpowers/4.1.1/skills/brainstorming
   209	
   210	# Brainstorming Ideas Into Designs
   211	
   212	## Overview
   213	
   214	This is verbose skill content that should not appear in summaries...`
   215	
   216		lines := []transcript.Line{
   217			{
   218				Type: "user",
   219				UUID: "user-1",
   220				Message: mustMarshal(t, transcript.UserMessage{
   221					Content: "Invoke the superpowers:brainstorming skill",
   222				}),
   223			},
   224			{
   225				Type: "assistant",
   226				UUID: "assistant-1",
   227				Message: mustMarshal(t, transcript.AssistantMessage{
   228					Content: []transcript.ContentBlock{
   229						{Type: "tool_use", Name: "Skill", Input: mustMarshal(t, transcript.ToolInput{Skill: "superpowers:brainstorming"})},
   230					},
   231				}),
   232			},
   233			{
   234				Type: "user",
   235				UUID: "user-2",
   236				Message: mustMarshal(t, transcript.UserMessage{
   237					Content: skillContent, // This should be filtered out
   238				}),
   239			},
   240			{
   241				Type: "user",
   242				UUID: "user-3",
   243				Message: mustMarshal(t, transcript.UserMessage{
   244					Content: "Now help me brainstorm a feature",
   245				}),
   246			},
   247		}
   248	
   249		entries := BuildCondensedTranscript(lines)
   250	
   251		// Should have: user prompt, tool call, user prompt (NOT the skill content)
   252		if len(entries) != 3 {
   253			t.Fatalf("expected 3 entries (skill content filtered), got %d", len(entries))
   254		}
   255	
   256		// Verify the skill content was filtered
   257		for _, entry := range entries {
   258			if entry.Type == EntryTypeUser && strings.Contains(entry.Content, "Base directory for this skill") {
   259				t.Error("skill content injection should have been filtered out")
   260			}
   261		}
   262	
   263		// Verify the real user messages are present
   264		if entries[0].Content != "Invoke the superpowers:brainstorming skill" {
   265			t.Errorf("first user message wrong: %s", entries[0].Content)
   266		}
   267		if entries[2].Content != "Now help me brainstorm a feature" {
   268			t.Errorf("last user message wrong: %s", entries[2].Content)
   269		}
   270	}
